python3 << 'EOF'
from docx import Document
import json
import re

# Load employee data
with open('employee_data.json', 'r') as f:
    data = json.load(f)

# Load the template
doc = Document('offer_letter_template.docx')

def replace_placeholders(text, data):
    """Replace placeholders in text with data values"""
    # Handle conditional relocation section
    if data.get('RELOCATION_PACKAGE') == 'Yes':
        # Keep the content but remove the IF/END_IF markers
        text = text.replace('{{IF_RELOCATION}}', '')
        text = text.replace('{{END_IF_RELOCATION}}', '')
    else:
        # Remove the entire conditional section including content
        text = re.sub(r'\{\{IF_RELOCATION\}\}.*?\{\{END_IF_RELOCATION\}\}', '', text, flags=re.DOTALL)

    # Replace all other placeholders
    for key, value in data.items():
        placeholder = '{{' + key + '}}'
        text = text.replace(placeholder, str(value))

    return text

# Process paragraphs
for para in doc.paragraphs:
    if para.text:
        new_text = replace_placeholders(para.text, data)
        if new_text != para.text:
            # Preserve formatting by replacing text in runs
            if para.runs:
                # Combine all runs text, replace, then put in first run and clear others
                full_text = ''.join(run.text for run in para.runs)
                new_full_text = replace_placeholders(full_text, data)
                para.runs[0].text = new_full_text
                for run in para.runs[1:]:
                    run.text = ''
            else:
                para.text = new_text

# Process tables if any
for table in doc.tables:
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                if para.text:
                    new_text = replace_placeholders(para.text, data)
                    if new_text != para.text:
                        if para.runs:
                            full_text = ''.join(run.text for run in para.runs)
                            new_full_text = replace_placeholders(full_text, data)
                            para.runs[0].text = new_full_text
                            for run in para.runs[1:]:
                                run.text = ''
                        else:
                            para.text = new_text

# Save the filled document
doc.save('/root/offer_letter_filled.docx')
print("Offer letter saved to /root/offer_letter_filled.docx")
EOF
